// pdfPresupuesto.js
// Lógica de generación del PDF del presupuesto, separada de PresupuestoNuevo.jsx.
// Contiene: el logo/membrete en base64, el armado del HTML/CSS del documento,
// y la generación + descarga del PDF (html2pdf.js + pdf-lib para fusionar adjuntos).

export const MEMBRETE_DANIEL_ROQUE_B64 ="data:image/png;base64,";

// generarPresupuestoPDF: arma el HTML del presupuesto con los datos recibidos
// y dispara la descarga del PDF. Recibe un solo objeto con todo lo que antes
// se tomaba por closure del componente PresupuestoNuevo.
//
// Parámetros esperados:
//  - querDescripcion: bool, si se incluye item.descripcion en el PDF
//  - fecha, numeroPres, numero, revision: datos del encabezado
//  - cliente, domicilio, localidad, telefono1, telefono2: datos del cliente
//  - observaciones, leyenda: textos libres
//  - lineasActivas: líneas de precio activas (1 a 3)
//  - presupuestoItems: ítems del presupuesto
//  - grupoDe: función (item) => nombre de sección/grupo
//  - mostrarCosto, incluirPrecio, incluirSubtotalItem, incluirTotal, agregarIVA, incluirTextoColoc: flags de armado
//  - incluirTextoSena: bool, si se agrega el recuadro de seña/condiciones (fondo amarillo)
//  - textoSena: texto libre de ese recuadro, editable desde el Encabezado
//  - imagenesFinal: fotos y PDFs adjuntos
//  - setGenerandoPDF: setter de estado para mostrar "Generando..." en el botón
export function generarPresupuestoPDF({
  querDescripcion,
  fecha,
  numeroPres,
  numero,
  revision,
  cliente,
  domicilio,
  localidad,
  telefono1,
  telefono2,
  observaciones,
  leyenda,
  lineasActivas,
  presupuestoItems,
  grupoDe,
  mostrarCosto,
  incluirPrecio,
  incluirSubtotalItem,
  incluirTotal,
  agregarIVA,
  incluirTextoColoc,
  incluirTextoSena,
  textoSena,
  imagenesFinal,
  setGenerandoPDF,
}) {
    const formatPeso = (v) =>
      "$" +
      Number(v || 0).toLocaleString("es-AR", { minimumFractionDigits: 2 });

    const fechaFmt = fecha
      ? new Date(fecha + "T00:00:00").toLocaleDateString("es-AR", {
          day: "2-digit",
          month: "long",
          year: "numeric",
        })
      : new Date().toLocaleDateString("es-AR", {
          day: "2-digit",
          month: "long",
          year: "numeric",
        });

    const nro =
      numeroPres != null
        ? String(numeroPres).padStart(5, "0")
        : numero !== "Nuevo"
          ? numero
          : "----";

    // Cantidad de columnas de la tabla según qué se decida incluir
    // Si hay líneas cargadas, se muestra una columna de precio por cada línea
    // (igual que en la tabla "Presupuesto" en pantalla). Si no hay líneas, se
    // usa la columna única "Precio unit." controlada por incluirPrecio.
    const mostrarLineas = lineasActivas.length > 0;

    // Agrupa los ítems por grupo personalizado (si el usuario le asignó uno)
    // o, en su defecto, por la sección automática de siempre. Respeta el
    // orden en que aparecen los ítems.
    const secciones = [...new Set(presupuestoItems.map((p) => grupoDe(p)))];

    // Genera un bloque <table> independiente por sección/grupo, con su propio
    // encabezado "Cant / Detalle / Línea X" y su fila de total — igual que el
    // formato clásico de presupuesto de Daniel Roque S.R.L. (una tabla por
    // sección, sin precio por ítem, solo el total de cada grupo).
    const seccionesHTML = secciones
      .map((sec) => {
        const items = presupuestoItems.filter((p) => grupoDe(p) === sec);
        const subtotalSec = items.reduce((s, it) => s + (it.subtotal || 0), 0);
        const subtotalesLineaSec = mostrarLineas
          ? lineasActivas.map((l, li) =>
              items.reduce((s, it) => {
                const pr =
                  parseFloat(it.precios?.[li]?.precio ?? it.precio ?? 0) || 0;
                return s + pr * (parseFloat(it.cantidad) || 1);
              }, 0),
            )
          : [];

        const filasItems = items
          .map((item) => {
            const medida =
              (item.seccion === "Mampara" || item.seccion === "Puerta") &&
              item.ancho &&
              item.alto
                ? ` <span class="medida">(${item.ancho} × ${item.alto} cm)</span>`
                : "";
            // Descripción del ítem (campo `descripcion`, separado del
            // nombre/artículo). Solo se muestra si el usuario dijo que sí
            // en el confirm() de más arriba, y solo si hay algo distinto
            // que mostrar (evita duplicar el mismo texto de nombreart).
            const descripcionHTML =
              querDescripcion && item.descripcion && item.descripcion !== item.nombreart
                ? `<div class="item-desc">${item.descripcion}</div>`
                : "";
            // Precio por ítem: SOLO se muestra si incluirPrecio está activo.
            // Por defecto queda oculto (igual que el formato clásico), y solo
            // se ven los totales por sección/grupo al final de cada tabla.
            const celdasPrecio = mostrarLineas
              ? lineasActivas
                  .map((l, li) => {
                    if (!incluirPrecio) return `<td class="right"></td>`;
                    const pr = item.precios?.[li]?.precio ?? item.precio ?? 0;
                    return `<td class="right">${formatPeso(pr)}</td>`;
                  })
                  .join("")
              : incluirPrecio
                ? `<td class="right">${formatPeso(item.precio)}</td>`
                : "";
            return `
        <tr>
          <td class="cant">${item.cantidad ?? 1}</td>
          <td>${item.nombreart ?? ""}${medida}${descripcionHTML}</td>
          ${mostrarCosto ? `<td class="right">${item.costo != null ? formatPeso(item.costo) : "—"}</td>` : ""}
          ${celdasPrecio}
          ${incluirSubtotalItem ? `<td class="right"><strong>${formatPeso(item.subtotal)}</strong></td>` : ""}
        </tr>`;
          })
          .join("");

        const labelColspan = 2 + (mostrarCosto ? 1 : 0);
        const celdasSubtotalLinea = mostrarLineas
          ? subtotalesLineaSec
              .map((st) => `<td class="right">${formatPeso(st)}</td>`)
              .join("")
          : incluirPrecio
            ? `<td class="right">${formatPeso(subtotalSec)}</td>`
            : "";
        const celdaSubtotalItem = incluirSubtotalItem
          ? `<td class="right">${formatPeso(subtotalSec)}</td>`
          : "";

        // Fotos asignadas manualmente a este grupo — se pegan justo debajo
        // del detalle/tabla del grupo correspondiente.
        const fotosSec = imagenesFinal.filter(
          (im) => im.tipo === "imagen" && im.grupo === sec,
        );
        const fotosSecHTML = fotosSec.length
          ? `<div class="sec-fotos" style="margin-top:10px;">${fotosSec
              .map(
                (im) =>
                  `<img src="${im.url}" style="max-width:100%; display:block; margin-top:8px;" />`,
              )
              .join("")}</div>`
          : "";

        return `
      <div class="sec-block">
        <div class="sec-title">${sec}:</div>
        <table>
          <thead>
            <tr>
              <th class="cant">Cant</th>
              <th>Detalle</th>
              ${mostrarCosto ? `<th class="right">Costo</th>` : ""}
              ${
                mostrarLineas
                  ? lineasActivas
                      .map((l) => `<th class="right">Línea ${l.linea}</th>`)
                      .join("")
                  : incluirPrecio
                    ? `<th class="right">Precio unit.</th>`
                    : ""
              }
              ${incluirSubtotalItem ? `<th class="right">Subtotal</th>` : ""}
            </tr>
          </thead>
          <tbody>
            ${filasItems}
            <tr class="subtotal-row">
              <td colspan="${labelColspan}">Total ${sec}:</td>
              ${celdasSubtotalLinea}
              ${celdaSubtotalItem}
            </tr>
          </tbody>
        </table>
        ${fotosSecHTML}
      </div>`;
      })
      .join("");

    const totalGeneral = presupuestoItems.reduce(
      (s, it) => s + (it.subtotal || 0),
      0,
    );

    // Total por cada línea presupuestada (1, 2 o 3), igual que el TOTAL GENERAL en pantalla
    const totalesPorLinea = mostrarLineas
      ? lineasActivas.map((l, li) =>
          presupuestoItems.reduce((s, it) => {
            const pr =
              parseFloat(it.precios?.[li]?.precio ?? it.precio ?? 0) || 0;
            return s + pr * (parseFloat(it.cantidad) || 1);
          }, 0),
        )
      : [];

    // Estilo "clásico" tipo máquina de escribir (mismo aspecto que los
    // presupuestos históricos de Daniel Roque S.R.L.): monoespaciado, blanco
    // y negro, títulos de sección en cursiva subrayada, y solo totales por
    // grupo (sin precio por ítem, salvo que se active incluirPrecio).
    const styleCSS = `
    @import url('https://fonts.googleapis.com/css2?family=Space+Mono:wght@400;700&display=swap');
    * { box-sizing: border-box; margin: 0; padding: 0; }
    body { font-family: 'Space Mono', 'Courier New', monospace; background: #fff; color: #111; font-size: 12px; }
    .page { width: 794px; min-height: 1123px; margin: 0 auto; padding: 30px 56px 40px; display: flex; flex-direction: column; background: #fff; }
    .membrete-banner { margin-bottom: 14px; }
    .membrete-banner img { max-width: 100%; max-height: 130px; height: auto; }
    .doc-nro-corner { text-align: right; font-size: 10px; color: #555; margin-bottom: 6px; }
    .doc-title { text-align: center; font-weight: 700; font-size: 15px; letter-spacing: 0.14em; text-transform: uppercase; margin-bottom: 14px; }
    .info-line { display: flex; justify-content: space-between; font-size: 12px; margin-bottom: 2px; }
    .info-line.right-only { justify-content: flex-end; }
    .body { flex: 1; margin-top: 18px; }
    .leyenda { font-size: 11px; font-style: italic; margin-bottom: 18px; }
    .sec-block { margin-bottom: 20px; }
    .sec-title { font-style: italic; font-weight: 700; text-transform: uppercase; font-size: 12px; margin-bottom: 3px; }
    table { width: 100%; border-collapse: collapse; font-size: 12px; }
    thead th { text-align: left; font-weight: 700; border-bottom: 1px solid #111; padding: 1px 8px 3px 0; }
    thead th.cant, td.cant { width: 44px; }
    thead th.right { text-align: right; }
    thead th.center { text-align: center; }
    tbody td { padding: 2px 8px 2px 0; vertical-align: top; }
    tbody td.right { text-align: right; }
    tbody td.center { text-align: center; }
    .medida { color: #444; font-size: 11px; }
    .item-desc { color: #444; font-size: 11px; font-style: italic; margin-top: 2px; }
    tr.subtotal-row td { border-top: 1px solid #111; font-weight: 700; padding-top: 4px; }
    .totals-final { margin-top: 6px; text-align: right; }
    .totals-final .t-row { font-weight: 700; font-size: 13px; padding: 3px 0; }
    .iva-note { font-size: 10px; color: #555; text-align: right; margin-top: 4px; }
    .clausula { font-size: 11px; color: #333; border-top: 1px dashed #999; padding-top: 8px; margin-top: 14px; margin-bottom: 14px; }
    .observaciones { font-size: 11px; color: #111; white-space: pre-wrap; margin-top: 10px; }
    .texto-sena { background: #fff59d; border: 1px solid #d4c400; border-radius: 4px; padding: 10px 12px; margin-top: 14px; font-size: 11px; font-weight: 700; white-space: pre-wrap; }
    .footer { margin-top: auto; border-top: 1px solid #111; padding-top: 8px; display: flex; justify-content: space-between; font-size: 10px; color: #333; }
    /* Evita que html2pdf corte una imagen a la mitad entre dos hojas A4:
       si no entra completa en lo que queda de página, la empuja entera a
       la siguiente. */
    img, .sec-fotos, .adjunto-imagen { page-break-inside: avoid; break-inside: avoid; }
    `;

    const pageHTML = `
<div class="page">
  <div class="membrete-banner">
    <img src="${MEMBRETE_DANIEL_ROQUE_B64}" alt="Daniel Roque S.R.L." />
  </div>
  <div class="doc-nro-corner">N° ${nro} — Rev. ${revision}</div>
  <div class="doc-title">Presupuesto</div>
  <div class="info-line">
    <span>Cliente: ${cliente || "Consumidor final"}${domicilio ? ` — ${domicilio}` : ""}</span>
    <span>Fecha: ${fechaFmt}</span>
  </div>
  <div class="info-line">
    <span>Localidad: ${localidad || "—"}</span>
    <span>Tel: ${telefono1 || telefono2 || "—"}</span>
  </div>

  <div class="body">
    ${leyenda ? `<div class="leyenda">${leyenda.replace(/\n/g, "<br/>")}</div>` : ""}

    ${seccionesHTML}

    ${
      incluirTotal
        ? `<div class="totals-final">
        ${
          mostrarLineas
            ? totalesPorLinea
                .map(
                  (t, li) =>
                    `<div class="t-row">TOTAL LÍNEA ${lineasActivas[li].linea}: ${formatPeso(t)}</div>`,
                )
                .join("")
            : `<div class="t-row">TOTAL: ${formatPeso(totalGeneral)}</div>`
        }
        ${agregarIVA ? `<div class="iva-note">Precios con IVA incluido, sujetos a reajustes</div>` : ""}
      </div>`
        : ""
    }

    ${
      incluirTextoColoc
        ? `<div class="clausula">La colocación no está incluida en este presupuesto, salvo que se indique lo contrario.</div>`
        : ""
    }

    ${
      observaciones
        ? `<div class="sec-title" style="margin-top:14px;">Observaciones</div><div class="observaciones">${observaciones.replace(/\n/g, "<br/>")}</div>`
        : ""
    }

    ${
      incluirTextoSena && textoSena
        ? `<div class="texto-sena">${textoSena.replace(/\n/g, "<br/>")}</div>`
        : ""
    }

    ${imagenesFinal
      .filter((im) => im.tipo === "imagen" && !im.grupo)
      .map(
        (im) =>
          `<div class="adjunto-imagen" style="margin-top:18px;"><img src="${im.url}" style="max-width:100%; display:block;" /></div>`,
      )
      .join("")}
  </div>
  <div class="footer">
    <div>Daniel Roque S.R.L. — Bahía Blanca</div>
    <div>Presupuesto N° ${nro} — Rev. ${revision}</div>
  </div>
</div>`;

    // Genera el PDF real en el cliente (html2pdf.js = html2canvas + jsPDF) y lo descarga.
    // Reemplaza al viejo mecanismo de window.print(), que dependía de que el
    // navegador abriera solo el diálogo de impresión — poco confiable en algunos
    // navegadores/extensiones.
    const generarDescarga = () => {
      setGenerandoPDF(true);
      const contenedor = document.createElement("div");
      contenedor.style.cssText =
        "position:fixed; left:-9999px; top:0; width:794px; background:#fff; z-index:-1;";
      contenedor.innerHTML = `<style>${styleCSS}</style>${pageHTML}`;
      document.body.appendChild(contenedor);

      const limpiar = () => {
        if (contenedor.parentNode) contenedor.parentNode.removeChild(contenedor);
        setGenerandoPDF(false);
      };

      const paginaEl = contenedor.querySelector(".page");
      const esperarFuentes =
        document.fonts && document.fonts.ready
          ? document.fonts.ready
          : Promise.resolve();

      const pdfsAdjuntos = imagenesFinal.filter((im) => im.tipo === "pdf");
      const necesitaFusionPDF = pdfsAdjuntos.length > 0;

      const cargarScript = (src) =>
        new Promise((resolve, reject) => {
          const s = document.createElement("script");
          s.src = src;
          s.onload = resolve;
          s.onerror = () => reject(new Error("No se pudo cargar " + src));
          document.head.appendChild(s);
        });

      const asegurarPDFLib = () =>
        window.PDFLib
          ? Promise.resolve()
          : cargarScript(
              "https://cdnjs.cloudflare.com/ajax/libs/pdf-lib/1.17.1/pdf-lib.min.js",
            );

      // Antes: format usaba scrollHeight, generando UNA sola página del
      // tamaño de todo el contenido. Eso hacía que, al imprimir en A4 real,
      // el corte entre hojas físicas cayera en cualquier punto (incluso en
      // medio de una foto), porque el PDF mismo no tenía páginas reales.
      // Ahora: alto fijo de A4 (1123px), para que html2pdf pagine de
      // verdad, + "pagebreak.avoid" para que nunca corte a la mitad de una
      // imagen (empuja la imagen entera a la página siguiente en su lugar).
      const opcionesPDF = {
        margin: 0,
        image: { type: "jpeg", quality: 0.98 },
        html2canvas: {
          scale: 2,
          useCORS: true,
          backgroundColor: "#ffffff",
        },
        jsPDF: {
          unit: "mm",
          format: "a4",
          orientation: "portrait",
        },
        pagebreak: {
          mode: ["css", "legacy"],
          avoid: ["img", ".sec-fotos", ".adjunto-imagen"],
        },
      };

      esperarFuentes
        .then(() => new Promise((resolve) => setTimeout(resolve, 300)))
        .then(() => (necesitaFusionPDF ? asegurarPDFLib() : Promise.resolve()))
        .then(async () => {
          if (necesitaFusionPDF) {
            // Genera el presupuesto como PDF en memoria y le agrega, al final,
            // las páginas del PDF adjuntado por el usuario.
            const pdfBase = await window
              .html2pdf()
              .set(opcionesPDF)
              .from(paginaEl)
              .outputPdf("arraybuffer");

            const { PDFDocument } = window.PDFLib;
            const docFinal = await PDFDocument.create();

            const docBase = await PDFDocument.load(pdfBase);
            const paginasBase = await docFinal.copyPages(
              docBase,
              docBase.getPageIndices(),
            );
            paginasBase.forEach((p) => docFinal.addPage(p));

            for (const pdfAdjunto of pdfsAdjuntos) {
              const bytesAdjunto = await fetch(pdfAdjunto.dataUrl).then((r) =>
                r.arrayBuffer(),
              );
              const docAdjunto = await PDFDocument.load(bytesAdjunto);
              const paginasAdjunto = await docFinal.copyPages(
                docAdjunto,
                docAdjunto.getPageIndices(),
              );
              paginasAdjunto.forEach((p) => docFinal.addPage(p));
            }

            const bytesFinal = await docFinal.save();
            const blob = new Blob([bytesFinal], { type: "application/pdf" });
            const url = URL.createObjectURL(blob);
            const a = document.createElement("a");
            a.href = url;
            a.download = `Presupuesto_${nro}.pdf`;
            document.body.appendChild(a);
            a.click();
            a.remove();
            URL.revokeObjectURL(url);
          } else {
            await window
              .html2pdf()
              .set({ ...opcionesPDF, filename: `Presupuesto_${nro}.pdf` })
              .from(paginaEl)
              .save();
          }
        })
        .catch((err) => {
          console.error("Error generando PDF:", err);
          alert("Ocurrió un error generando el PDF. Probá de nuevo.");
        })
        .finally(limpiar);
    };

    if (window.html2pdf) {
      generarDescarga();
    } else {
      const script = document.createElement("script");
      script.src =
        "https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js";
      script.onload = generarDescarga;
      script.onerror = () => {
        alert(
          "No se pudo cargar el generador de PDF. Revisá la conexión a internet e intentá de nuevo.",
        );
      };
      document.head.appendChild(script);
    }
}
